"use strict";
/**
 * lib/ownMessageGuard.js - tells apart messages the BOT sent from messages a PERSON typed on the
 * bot's own WhatsApp account. Both arrive as "fromMe", and the bot must never run its own replies
 * as commands (that would loop forever).
 *
 * How it works: every message the bot sends gets an ID that is remembered BEFORE it is sent, so the
 * incoming copy of that message is recognised immediately. A message is treated as "typed by a person"
 * only when its ID was not generated by the bot AND does not look like a library-generated ID.
 */
const MAX_REMEMBERED = 3000;

function install(client, generateMessageID) {
  const sent = new Set();
  const order = [];

  const remember = (id) => {
    if (!id || sent.has(id)) return;
    sent.add(id);
    order.push(id);
    if (order.length > MAX_REMEMBERED) sent.delete(order.shift());
  };

  // Code that sends with relayMessage (button messages) registers its message ids here.
  if (client) client.rememberSentId = remember;

  const active = typeof generateMessageID === "function" && client && typeof client.sendMessage === "function";
  if (active) {
    const original = client.sendMessage.bind(client);
    client.sendMessage = (jid, content, options) => {
      const opts = options && typeof options === "object" ? { ...options } : {};
      if (!opts.messageId) opts.messageId = generateMessageID();
      remember(opts.messageId);
      return original(jid, content, opts);
    };
  }

  return {
    active,
    isBotSent: (id) => sent.has(id),
    /** true only for a message that a person typed by hand on the bot's own account */
    isTypedByHuman: (id) => active && typeof id === "string" && id.length > 0 && !sent.has(id) && !/^3EB0/i.test(id),
  };
}

module.exports = { install };
